let payload,group='전체',stock='',period=3653;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=(v,d=3)=>v.toLocaleString('ko-KR',{maximumFractionDigits:d});const stamp=s=>s?new Date(s).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'미수집';
function cutoff(p=period){const d=new Date();d.setUTCHours(0,0,0,0);d.setUTCFullYear(d.getUTCFullYear()-({3653:10,1826:5,1096:3,366:1}[p]||0));return +d;}
function points(id){const raw=payload.db.series[id]||[];const latest=raw.at(-1);return latest?raw.filter(r=>r.source===latest.source):[];}
function age(date){return Math.floor((Date.now()-Date.parse(date))/86400000);}
function niceStep(span,target=4){const raw=span/target||1,p=Math.pow(10,Math.floor(Math.log10(raw)));const m=raw/p;return (m<=1?1:m<=2?2:m<=2.5?2.5:m<=5?5:10)*p;}
function fmtTick(v,step){if(Math.abs(v)>=100000)return n(v/1000,0)+'k';if(Math.abs(v)>=10000)return n(v/1000,1)+'k';const d=step>=1?0:step>=.1?1:2;return n(v,d);}
function xTicks(first,last){const span=(last-first)/864e5,stepM=span>2200?12:span>1100?6:span>450?3:span>160?2:1,out=[];const d=new Date(first);d.setUTCHours(0,0,0,0);d.setUTCDate(1);d.setUTCMonth(Math.ceil(d.getUTCMonth()/stepM)*stepM);if(d.getTime()<first)d.setUTCMonth(d.getUTCMonth()+stepM);while(d.getTime()<=last){out.push({t:d.getTime(),label:stepM>=12?String(d.getUTCFullYear()):String(d.getUTCFullYear()).slice(2)+'.'+String(d.getUTCMonth()+1).padStart(2,'0')});d.setUTCMonth(d.getUTCMonth()+stepM);}return out;}
function chartVals(rows){let vals=rows;if(period){const cut=cutoff();vals=rows.filter(r=>Date.parse(r.date)>=cut);}return vals;}
function chart(rows,item){if(!rows.length)return '<div class="empty"><span>아직 수집된 관측값이 없습니다</span><small>연결 전 · 임의값으로 채우지 않음</small></div>';const vals=chartVals(rows);if(!vals.length)return '<div class="empty">선택한 기간에 관측값이 없습니다</div>';
 const bars=item.chart==='bars',W=360,H=160,L=40,R=50,T=12,B=20;let lo=Math.min(...vals.map(v=>v.value)),hi=Math.max(...vals.map(v=>v.value));if(bars){lo=Math.min(lo,0);hi=Math.max(hi,0);}if(hi===lo){lo-=Math.abs(lo)*.05||1;hi+=Math.abs(hi)*.05||1;}
 const step=niceStep(hi-lo,4);let ylo=Math.floor(lo/step)*step,yhi=Math.ceil(hi/step)*step;if(yhi-hi<step*.2)yhi+=step;if(lo-ylo<step*.2&&!(bars&&ylo===0&&lo>=0))ylo-=step;
 const first=period?cutoff():Date.parse(vals[0].date),last=period?Date.now():Date.parse(vals.at(-1).date);const x=v=>L+(last===first?(W-L-R)/2:(Date.parse(v.date)-first)/(last-first)*(W-L-R));const xt=t=>L+(t-first)/(last-first)*(W-L-R);const y=v=>T+(yhi-v)/(yhi-ylo)*(H-T-B);
 const mean=vals.reduce((a,v)=>a+v.value,0)/vals.length,lastV=vals.at(-1),dec=Math.abs(yhi)>=1000?0:Math.abs(yhi)>=100?1:2;
 let grid='';for(let v=ylo;v<=yhi+step*1e-6;v+=step){const yy=y(v);grid+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${yy.toFixed(1)}" y2="${yy.toFixed(1)}"/><text class="ytick" x="${L-6}" y="${(yy+3).toFixed(1)}" text-anchor="end">${fmtTick(v,step)}</text>`;}
 const ticks=xTicks(first,last).map(t=>{const xx=xt(t.t);return `<line class="xtick" x1="${xx.toFixed(1)}" x2="${xx.toFixed(1)}" y1="${H-B}" y2="${H-B+4}"/><text class="xlabel" x="${xx.toFixed(1)}" y="${H-6}" text-anchor="middle">${t.label}</text>`;}).join('');
 const axis=`<line class="axis" x1="${L}" x2="${W-R}" y1="${H-B}" y2="${H-B}"/>`;
 const meanLine=`<line class="meanline" x1="${L}" x2="${W-R}" y1="${y(mean).toFixed(1)}" y2="${y(mean).toFixed(1)}"/>`;
 const ly=Math.min(Math.max(y(lastV.value),T+7),H-B-7),ltxt=n(lastV.value,dec),lw=ltxt.length*5.6+8;
 const label=`<g class="vlabel"><line x1="${W-R}" x2="${W-R+3}" y1="${y(lastV.value).toFixed(1)}" y2="${ly.toFixed(1)}"/><rect x="${W-R+4}" y="${(ly-7).toFixed(1)}" width="${lw.toFixed(1)}" height="14" rx="3"/><text x="${(W-R+4+lw/2).toFixed(1)}" y="${(ly+3.5).toFixed(1)}" text-anchor="middle">${ltxt}</text></g>`;
 let marks;
 if(bars){const bw=Math.max(.8,(W-L-R)/vals.length*.82),y0=y(0);marks=`<line class="zero" x1="${L}" x2="${W-R}" y1="${y0.toFixed(1)}" y2="${y0.toFixed(1)}"/>`+vals.map(v=>{const yy=y(v.value);return `<rect class="bar ${v.value>=0?'pos':'neg'}" x="${(x(v)-bw/2).toFixed(2)}" y="${Math.min(yy,y0).toFixed(2)}" width="${bw.toFixed(2)}" height="${Math.max(.6,Math.abs(yy-y0)).toFixed(2)}"><title>${esc(v.date)} · ${n(v.value,2)} ${esc(item.unit)}</title></rect>`;}).join('');}
 else{const gap=item.frequency==='월간'?70:item.frequency==='분기'?150:item.frequency==='연간'?500:10;const segs=[];let cur=[];vals.forEach((v,i)=>{if(i&&(Date.parse(v.date)-Date.parse(vals[i-1].date))/864e5>=gap){segs.push(cur);cur=[];}cur.push(v);});segs.push(cur);
  const path=segs.map(s=>s.map((v,i)=>`${i?'L':'M'}${x(v).toFixed(2)},${y(v.value).toFixed(2)}`).join(' ')).join(' ');
  const area=segs.filter(s=>s.length>1).map(s=>`M${x(s[0]).toFixed(2)},${(H-B).toFixed(1)} `+s.map(v=>`L${x(v).toFixed(2)},${y(v.value).toFixed(2)}`).join(' ')+` L${x(s.at(-1)).toFixed(2)},${(H-B).toFixed(1)} Z`).join(' ');
  const dots=vals.length<=70?vals.map(v=>`<circle class="point" cx="${x(v).toFixed(2)}" cy="${y(v.value).toFixed(2)}" r="2.2"/>`).join(''):'';
  const hits=vals.length<=1500?vals.map(v=>`<circle class="hit" cx="${x(v).toFixed(2)}" cy="${y(v.value).toFixed(2)}" r="${vals.length>300?3:5}"><title>${esc(v.date)} · ${n(v.value,dec)} ${esc(item.unit)}</title></circle>`).join(''):'';
  marks=`<path class="area" d="${area}"/><path class="line" d="${path}"/>${dots}${hits}<circle class="end" cx="${x(lastV).toFixed(2)}" cy="${y(lastV.value).toFixed(2)}" r="3.6"/>`;}
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(item.name)} ${esc(vals[0].date)}부터 ${esc(vals.at(-1).date)}까지 ${vals.length}개 관측값"><title>${esc(item.name)} · ${vals.length}개 실제 관측값</title>${grid}${axis}${ticks}${meanLine}${marks}${label}</svg>`;}
function legend(rows,item){const vals=chartVals(rows);if(!vals.length)return '';const mean=vals.reduce((a,v)=>a+v.value,0)/vals.length,dec=Math.abs(mean)>=1000?0:Math.abs(mean)>=100?1:2;const lg=item.legend||{};
 if(item.chart==='bars')return `<div class="legend"><span><i class="sw bar pos"></i>${esc(lg.pos||'양(+)')}</span><span><i class="sw bar neg"></i>${esc(lg.neg||'음(−)')}</span><span><i class="sw dash"></i>기간 평균 ${n(mean,dec)}</span><span><i class="sw zero"></i>0선</span></div>`;
 return `<div class="legend"><span><i class="sw line"></i>${esc(lg.series||item.sourceHint||'관측값')}</span><span><i class="sw dot"></i>최신 ${esc(vals.at(-1).date)}</span><span><i class="sw dash"></i>기간 평균 ${n(mean,dec)}</span></div>`;}
// 변동 표기: 주 뱃지는 직전 관측 대비(일간=전 거래일, 월간=전월, 연간=전년). 보조 줄은 1주·1개월·전년 동기.
const primaryLabel=(f,id)=>f==='일간'?'전일':f==='주간'?(id==='rec'?'직전 거래일':'전주'):f==='월간'?'전월':f==='분기'?'전분기':f==='연간'?'전년':'직전';
function diffText(a,b,unit){const c=a.value-b.value,f=(v,d,u)=>{const r=Number(v.toFixed(d));return (r>0?'+':'')+n(r===0?0:r,d)+u;};if(unit==='%')return f(c,2,'%p');if(unit==='°C')return f(c,1,'°C');if(unit==='USD/MMBtu'&&(a.id==='jkm_fei'||a.id==='jkm_hh'))return f(c,2,' $');return b.value!==0?f(c/Math.abs(b.value)*100,2,'%'):'비교 불가';}
function baseBefore(rows,last,days,tol){const target=Date.parse(last.date)-days*86400000;const b=rows.findLast(r=>Date.parse(r.date)<=target);return b&&b!==last&&target-Date.parse(b.date)<=tol*86400000?b:null;}
function compareList(rows,item){const last=rows.at(-1),f=item.frequency,out=[];const add=(label,b)=>{if(b)out.push({label,from:b.date,text:diffText(last,b,item.unit),cls:last.value>b.value?'rise':last.value<b.value?'fall':'neutral'});};
 if(f==='일간'||f==='주간'){add('1주',baseBefore(rows,last,7,6));add('1개월',baseBefore(rows,last,30,10));add('전년',baseBefore(rows,last,365,15));}
 else if(f==='월간'){add('3개월',baseBefore(rows,last,89,35));add('전년동월',rows.find(r=>r.date===(Number(last.date.slice(0,4))-1)+last.date.slice(4))||null);}
 else if(f==='분기'){add('전년동기',baseBefore(rows,last,365,50));}
 return out;}
function card(item){const rows=points(item.id),last=rows.at(-1),prev=rows.at(-2),stale=last&&age(last.date)>item.staleDays;let delta='이전 관측값 없음';if(prev)delta=diffText(last,prev,item.unit)+' <small>'+primaryLabel(item.frequency,item.id)+'</small>';const compares=last?compareList(rows,item):[];const latestRun=payload.db.runs.at(-1)?.results.find(r=>r.ids?.includes(item.id));const failed=latestRun&&!latestRun.ok;return `<article class="card" data-id="${item.id}" data-group="${esc(item.group)}"><div class="card-top"><div><h3>${esc(item.name)}</h3></div><button class="expand" data-expand="${item.id}" aria-label="${esc(item.name)} 확대">⤢</button><span class="badge ${!last||stale||failed?'warn':''}">${!last?'연결 대기':failed?'수집 오류':stale?'발표/갱신 확인':item.frequency}</span></div><div class="metric"><span class="value">${last?n(last.value):'—'}</span><span class="unit">${esc(item.unit)}</span><span class="change ${last&&prev&&last.value>prev.value?'rise':'fall'}">${delta}</span></div><div class="date">${last?'관측 '+esc(last.date)+(item.frequency==='월간'?' · 해당 월 기준':'')+(prev?' · 비교 기준 '+esc(prev.date):''):'필요 원천: '+esc(item.sourceHint||'원천 연결 확인 중')}</div><div class="compare">${compares.map(c=>`<span class="${c.cls}" title="${esc(c.from)} 대비"><small>${c.label}</small> ${c.text}</span>`).join('')}</div><div class="chart">${chart(rows,item)}</div>${legend(rows,item)}<div class="stock-tags">${[...new Set(item.effects.flatMap(e=>e.codes))].map(c=>esc(payload.stocks[c])).join(' · ')}</div><details class="impact"><summary>실적 영향 · 시차 · 출처</summary><div class="history"><span>${rows.length.toLocaleString()}개 관측${period&&last&&Date.parse(rows[0].date)>cutoff()+45*86400000?' · 선택 기간 일부':''}</span><span>${last?rows[0].date+' ~ '+last.date:'미수집'}</span></div><p class="definition">${esc(item.definition)}</p>${item.effects.map(e=>`<div class="effect"><div>${e.codes.map(c=>`<b>${esc(payload.stocks[c]||c)}</b><small>${c}</small>`).join('')}</div><div>${e.direction?`<p class="direction-strip"><span class="direction ${e.direction.up}">상승: ${e.direction.up}</span> <span class="direction ${e.direction.down}">하락: ${e.direction.down}</span><small> 조건부 실적 영향</small></p>`:""}<p>${esc(e.text)}</p><div class="lag">시차 · ${esc(e.lag)} ${(e.auditSources||[payload.sources[e.ref]]).map((s,i)=>`<a href="${esc(s.url)}" target="_blank" rel="noopener" title="${esc(s.title||s.name)}">근거 ${i+1} ↗</a>`).join(" · ")} ${e.analysisUrl?`<a href="${esc(e.analysisUrl)}">주가 시차·수치 비교 →</a>`:""}</div></div></div>`).join('')}<div class="source"><span>${last?esc(last.source):'미수집'}${last?' · 수집 '+esc(stamp(last.collectedAt)):''}</span>${last?`<a href="${esc(last.url)}" target="_blank" rel="noopener">원문 ↗</a>`:''}</div></details></article>`;}
function renderOilCurve(){const c=payload.oilCurve;const el=$('oil-curve');if(!el)return;if(!c||!c.wti?.length){el.innerHTML='<p class="muted">월물 커브 미수집</p>';return;}
 const months=[...new Set([...c.wti,...c.brent].map(x=>x.contract))].sort();const w0=c.wti[0]?.price,b0=c.brent[0]?.price;const cell=(list,base)=>m=>{const x=list.find(y=>y.contract===m);if(!x)return '<td class="num">–</td>';const d=x.price-base;return `<td class="num">${x.price.toFixed(2)}<small> ${d>0?'+':''}${d.toFixed(2)}</small></td>`;};
 const slope=(list)=>{const f=list[0],t=list.find(x=>x.contract>=f.contract.replace(/^(\d{4})/,(_,y)=>String(Number(y)+1)))||list.at(-1);return f&&t?`${f.contract} ${f.price.toFixed(2)} → ${t.contract} ${t.price.toFixed(2)} (${((t.price/f.price-1)*100).toFixed(1)}%, ${t.price<f.price?'백워데이션':'콘탱고'})`:'';};
 el.innerHTML=`<p><b>WTI</b> ${slope(c.wti)} · <b>Brent</b> ${slope(c.brent)} · 조회 ${esc(c.asOf.slice(0,16).replace('T',' '))} UTC</p><div class="table-wrap"><table><thead><tr><th>월물</th>${months.map(m=>`<th>${m.slice(2).replace('-','/')}</th>`).join('')}</tr></thead><tbody><tr><td>WTI (USD/bbl)</td>${months.map(cell(c.wti,w0)).join('')}</tr><tr><td>Brent (USD/bbl)</td>${months.map(cell(c.brent,b0)).join('')}</tr></tbody></table></div><p class="muted">작은 숫자는 최근월 대비 차이. 출처 Yahoo Finance 개별 월물(CL·BZ, .NYM), 장중 가격 포함.</p>`;}
function render(){ renderOilCurve(); $('history-coverage').innerHTML=payload.catalog.map(c=>{const r=points(c.id);return '<tr><td>'+esc(c.name)+'</td>'+[3653,1826,1096,366].map(d=>'<td>'+n(r.filter(x=>Date.parse(x.date)>=cutoff(d)).length,0)+'</td>').join('')+'<td>'+(r.length?r[0].date+' ~ '+r.at(-1).date:'미수집')+'</td></tr>';}).join('');$('period-buttons').innerHTML=[[3653,'10년'],[1826,'5년'],[1096,'3년'],[366,'1년']].map(([v,label])=>'<button data-period="'+v+'" aria-pressed="'+(period===v)+'" class="'+(period===v?'active':'')+'">'+label+'</button>').join('');$('period-buttons').querySelectorAll('button').forEach(b=>b.onclick=()=>{period=Number(b.dataset.period);$('period').value=String(period);render();});const opened=[...document.querySelectorAll('#cards .card details[open],#pending-cards .card details[open]')].map(d=>d.closest('.card').dataset.id);const available=payload.catalog.filter(c=>points(c.id).length).length;const lastRun=payload.db.runs.at(-1);$('updated').innerHTML=`${new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric'})}<br>마지막 공개원천 확인 ${esc(stamp(lastRun?.at))}`;
 $('coverage').textContent=`${available}개 지표 수집 · ${payload.catalog.reduce((a,c)=>a+(payload.db.series[c.id]?.length||0),0).toLocaleString()}개 실제 관측값 · 매일 자동 갱신`;
 $('tabs').innerHTML=['전체','핵심','에너지','전력·요금','수요·가동','금리·환율','상사·원자재'].map(g=>`<button data-group="${g}" class="${group===g?'active':''}">${g}</button>`).join('');$('tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{group=b.dataset.group;render();});
 const filtered=payload.catalog.filter(c=>(group==='전체'||group==='핵심'&&c.priority==='핵심'||c.group===group)&&(!stock||c.effects.some(e=>e.codes.includes(stock))));filtered.sort((a,b)=>Number(!!points(b.id).length)-Number(!!points(a.id).length));$('cards').innerHTML=['에너지','전력·요금','수요·가동','금리·환율','상사·원자재'].map(g=>{const cs=filtered.filter(c=>c.group===g&&points(c.id).length);cs.sort((a,b)=>Number(points(b.id).length>1)-Number(points(a.id).length>1));return cs.length?'<section><div class="section-head"><h2>'+g+'</h2><span>'+cs.length+'개 지표</span></div><div class="grid">'+cs.map(card).join('')+'</div></section>':'';}).join('');const pending=filtered.filter(c=>!points(c.id).length);$('pending-title').textContent='연결 대기 지표 · '+pending.length+'개';$('pending-cards').innerHTML=pending.map(card).join('');document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{const c=payload.catalog.find(c=>c.id===b.dataset.expand);$('detail-title').textContent=c.name;$('detail-body').innerHTML=card(c);$('detail-body').querySelector('[data-expand]').remove();$('detail-body').querySelector('details').open=true;$('detail').showModal();});table();
 $('notice').textContent=`${filtered.filter(c=>points(c.id).length).length}개 차트 · 뱃지는 직전 관측 대비(전일/전월/전년), 아래 줄은 1주·1개월·전년 비교 · 색상은 주가 전망이 아닙니다.`;
 $('sources').innerHTML=payload.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('');
 $('health').innerHTML=(lastRun?.results||[]).map(r=>`<div class="health-row"><b>${esc(r.name)}</b><span>${r.ok?'정상 · '+r.count+'개 관측값':'실패 · '+esc(r.error)}</span></div>`).join('')+`<div class="health-row"><b>BigFinance</b><span>${payload.monitor?esc(stamp(payload.monitor.checkedAt))+' · '+esc(payload.monitor.note):'자동 확인 기록 없음 · 로그인 세션 필요'}</span></div>`;
 for(const d of document.querySelectorAll('.card details'))if(opened.includes(d.closest('.card').dataset.id))d.open=true; $('ids').textContent=payload.catalog.map(c=>`${c.id} → ${c.name} (${c.unit})`).join('\n');}
async function load(){const r=await fetch('/api/data');if(!r.ok)throw Error('로컬 데이터 읽기 실패');const next=await r.json();payload=next;if(!$('data-series').options.length)for(const c of payload.catalog)$('data-series').add(new Option(c.name,c.id));if($('stock').options.length===1)for(const [code,name] of Object.entries(payload.stocks))$('stock').add(new Option(name,code));render();}
 $('stock').onchange=e=>{stock=e.target.value;render();};$('period').onchange=e=>{period=Number(e.target.value);render();};$('refresh').onclick=async()=>{const b=$('refresh');b.disabled=true;b.textContent='공개 원천 확인 중…';try{const r=await fetch('/api/refresh',{method:'POST'});if(!r.ok)throw Error((await r.json()).error);await load();}catch(e){$('notice').textContent=e.message;}finally{b.disabled=false;b.textContent='공개 데이터 갱신 ↻';}};
 $('import').onclick=async()=>{const f=$('csv').files[0];if(!f){$('notice').textContent='CSV 파일을 선택하세요.';return;}try{const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await f.text()});const j=await r.json();if(!r.ok)throw Error(j.error);await load();$('notice').textContent=`${j.count}개 관측값 반영 완료`;}catch(e){$('notice').textContent=e.message;}};
load().catch(e=>{$('notice').textContent=e.message;});

setInterval(async()=>{try{const r=await fetch('/api/data');const next=await r.json();if(next.db.updatedAt!==payload.db.updatedAt){payload=next;render();}}catch{}},60000);

let page=0;function table(){const id=$('data-series').value;if(!id)return;const c=payload.catalog.find(c=>c.id===id),rows=[...(payload.db.series[id]||[])].reverse();page=Math.max(0,Math.min(page,Math.ceil(rows.length/100)-1));$('data-count').textContent=c.name+' · '+rows.length.toLocaleString()+'개 관측값';$('data-rows').innerHTML=rows.slice(page*100,page*100+100).map(r=>'<tr><td>'+r.date+'</td><td>'+n(r.value)+'</td><td>'+esc(c.unit)+'</td><td><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.source)+'</a></td><td>'+stamp(r.collectedAt)+'</td></tr>').join('');$('page-label').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/100));$('prev').disabled=page===0;$('next').disabled=(page+1)*100>=rows.length;}$('data-series').onchange=()=>{page=0;table();};$('prev').onclick=()=>{page--;table();};$('next').onclick=()=>{page++;table();};$('close-detail').onclick=()=>$('detail').close();

document.addEventListener('pointermove',ev=>{const el=ev.target.closest('.chart');if(!el)return;const id=el.closest('[data-id]').dataset.id,c=payload.catalog.find(c=>c.id===id),all=points(id),rows=period?all.filter(r=>Date.parse(r.date)>=cutoff()):all,svg=el.querySelector('svg');if(!rows.length||!svg)return;let tip=el.querySelector('.tooltip');if(!tip){tip=document.createElement('div');tip.className='tooltip';el.append(tip);}const pt=svg.createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;const x=pt.matrixTransform(svg.getScreenCTM().inverse()).x,f=Math.max(0,Math.min(1,(x-42)/308)),target=(period?cutoff():Date.parse(rows[0].date))+f*(period?Date.now()-cutoff():Date.parse(rows.at(-1).date)-Date.parse(rows[0].date));let left=0,right=rows.length-1;while(left<right){const mid=Math.floor((left+right)/2);if(Date.parse(rows[mid].date)<target)left=mid+1;else right=mid;}let r=rows[left];if(left&&target-Date.parse(rows[left-1].date)<Date.parse(r.date)-target)r=rows[left-1];tip.textContent=r.date+' · '+n(r.value)+' '+c.unit;tip.style.display='block';});document.addEventListener('pointerout',ev=>{const el=ev.target.closest('.chart');if(el&&!el.contains(ev.relatedTarget)){const tip=el.querySelector('.tooltip');if(tip)tip.style.display='none';}});

$('paste-import').onclick=async()=>{try{const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:$('paste-csv').value});const j=await r.json();if(!r.ok)throw Error(j.error);await load();$('notice').textContent=j.count+'개 원자료 반영 완료';$('paste-csv').value='';}catch(e){$('notice').textContent=e.message;}};
